def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Markers select one contiguous edge word by matching color, then place
    # that word so its matching occurrence stays at the marker location.
    for r in range(1, h - 1):
        for c, v in enumerate(grid[r]):
            if not v:
                continue
            candidates = []
            for edge in (grid[0], grid[-1]):
                i = 0
                while i < w:
                    if edge[i] == 0:
                        i += 1
                        continue
                    j = i
                    while j < w and edge[j] != 0:
                        j += 1
                    word = edge[i:j]
                    if v in word:
                        candidates.append((word, word.index(v)))
                    i = j
            if candidates:
                word, pos = max(candidates, key=lambda x: len(x[0]))
                start = c - pos
                for k, color in enumerate(word):
                    x = start + k
                    if 0 <= x < w:
                        out[r][x] = color
    return out
