def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The boundary encodes two words: top runs (if any) and bottom runs.
    # Place the matching word so its marker color occupies the seed location.
    words = []
    for edge in (grid[0], grid[-1]):
        i = 0
        while i < w:
            if edge[i] == 0:
                i += 1
                continue
            j = i
            while j < w and edge[j] != 0:
                j += 1
            words.append(edge[i:j])
            i = j
    for r in range(1, h - 1):
        for c, color in enumerate(grid[r]):
            if color == 0:
                continue
            for word in words:
                if color not in word:
                    continue
                start = c - word.index(color)
                for k, value in enumerate(word):
                    x = start + k
                    if 0 <= x < w:
                        out[r][x] = value
